import {FACTORIES,SLOTS,SECTIONS,CHECKS} from './rules-data.js';
import {mode,ownerUid,portalHome,isOwner,currentUser,init,signIn,signOut,listDocs,saveDoc,deleteDoc,makeId} from './firebase.js';
import {workbook,downloadBlob} from './excel.js';
const $=s=>document.querySelector(s);
const H=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const now=()=>new Date().toLocaleString('zh-TW',{hour12:false});
const clean=x=>String(x??'').trim();
const stText={normal:'正常',abnormal:'異常',na:'不適用',pending:'尚未確認'};
const state={tab:'duty',events:[],staff:[],reports:[],incidents:[],rules:[],notes:[],revisions:[],settings:[],eventId:'',slotId:'08',sectionId:'preparation',drafts:{},editPeopleId:null,incidentEditId:null,reportPreview:'',authLoading:true};
let reloadBusy=false;
function toast(message,kind='info'){const d=$('#toast');d.textContent=message;d.style.background=kind==='error'?'#ad3737':'#154e78';d.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>d.style.display='none',4300);}
function ownerBlock(){return !isOwner()?`<div class="banner warning">你目前為唯讀權限。依本系統設定，只有指定管理員可新增、修改及刪除資料。</div>`:'';}
function disabled(){return isOwner()?'':'disabled';}
function warnDemo(){return mode==='demo'?`<div class="banner warning"><b>本機示範模式</b>：資料只存在這個瀏覽器的 localStorage，不會同步到 Firebase，也不能視為正式值勤紀錄。正式部署必須依部署說明設定 config.js 與 Firestore Rules。</div>`:'';}
function userLabel(){let c=currentUser();$('#accountLabel').textContent=c?.email||'未登入';$('#connectionLabel').textContent=mode==='demo'?'DEMO 示範':c?'Firebase 已登入':'Firebase 未登入';$('#homeBtn').href=portalHome;}
async function refresh(){if(reloadBusy)return;reloadBusy=true;try{const keys=['events','staff','reports','incidents','rules','notes','revisions','settings'];const data=await Promise.all(keys.map(k=>listDocs(k)));keys.forEach((k,i)=>state[k]=data[i]);state.events.sort((a,b)=>(b.date||'').localeCompare(a.date||''));if(!state.events.some(e=>e.id===state.eventId))state.eventId=state.events[0]?.id||'';render();}catch(e){mainError(e);}finally{reloadBusy=false;}}
function mainError(e){console.error(e);$('#main').innerHTML=`<div class="panel"><h2>讀取失敗</h2><p class="danger">${H(e.message)}</p><div class="banner warning">請檢查 Firebase 設定、授權網域、登入狀態及 Firestore Rules；不要直接覆蓋現有正式規則。</div><button class="btn" data-action="refresh">重新讀取</button></div>`;}
function eventNow(){return state.events.find(e=>e.id===state.eventId)||null;}
function staffNow(){const e=eventNow();return state.staff.filter(p=>p.factory===e?.factory&&p.active!==false).sort((a,b)=>(a.name||'').localeCompare(b.name||'','zh-Hant'));}
function reportStored(){return state.reports.find(r=>r.eventId===state.eventId&&r.slotId===state.slotId)||null;}
function draftKey(){return `${state.eventId}__${state.slotId}`;}
function initialDraft(){const saved=reportStored();if(saved)return structuredClone(saved);
 const e=eventNow(),slot=SLOTS.find(x=>x.id===state.slotId);const setting=state.settings.find(x=>x.id==='general')||{};const units=(setting.units?.[e?.factory]||[]).filter(Boolean);
 return {id:state.eventId+'__'+state.slotId,eventId:state.eventId,slotId:state.slotId,reportDate:e?.date||today(),peopleIds:[],checks:{},notes:{},unitAttendance:units.length?units.map(name=>({id:makeId(),unit:name,expected:'',actual:'',note:''})):[{id:makeId(),unit:'',expected:'',actual:'',note:''}],weather:{avg:'',max:'',direction:'',rain:'',station:'',observationTime:'',conditions:''},patrol:{result:'',time:'',note:''},status:'draft',savedAt:'',reportText:''};}
function draft(){const k=draftKey();if(!state.drafts[k])state.drafts[k]=initialDraft();return state.drafts[k];}
const slotNow=()=>SLOTS.find(s=>s.id===state.slotId)||SLOTS[0];
function setTab(t){state.tab=t;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);}
function render(){userLabel();$$nav();const c=$('#main');c.innerHTML=warnDemo()+(state.tab==='duty'?renderDuty():state.tab==='events'?renderEvents():state.tab==='people'?renderPeople():state.tab==='rules'?renderRules():state.tab==='history'?renderHistory():renderSettings());}
function $$nav(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));}
function panel(n,title,body,cls=''){return `<section class="panel ${cls}"><h2 class="section-title"><span class="number">${n}</span>${title}</h2>${body}</section>`;}
function empty(t){return `<div class="empty">${t}</div>`;}
const opts=(items,selected)=>items.map(([v,t])=>`<option value="${H(v)}" ${String(v)===String(selected)?'selected':''}>${H(t)}</option>`).join('');
function renderDuty(){const e=eventNow();if(!e)return panel('1','值勤作業',`<div class="banner">目前沒有颱風事件，請先建立事件，再設定各廠區值勤人員及各時段Checklist。</div><button class="btn" data-action="open-event">＋建立第一筆颱風事件</button>`);
 const d=draft(),s=slotNow(),saved=reportStored(),allStaff=staffNow();const summary=`${e.name}｜${e.factory}｜${e.date}`;
 const header=panel('1','颱風事件基本資料',`<div class="toolbar"><div class="field" style="min-width:230px"><label>選擇颱風事件（含廠區）</label><select data-global="event">${opts(state.events.map(e=>[e.id,`${e.name}／${e.factory}／${e.date}`]),e.id)}</select></div><div class="field"><label>目前廠區</label><input readonly value="${H(e.factory)}"></div><div class="field"><label>本次回報日期</label><input type="date" data-field="reportDate" value="${H(d.reportDate)}" ${disabled()}></div><button class="btn secondary" data-action="open-event">＋事件</button><button class="btn secondary" data-tab="people">值勤人員管理</button></div><div class="hint">事件：${H(summary)}。各廠區值勤人員名單與資料獨立；這裡不設置「整日值勤人員」，一律在下方各時段個別選擇。</div>`);
 const slots=panel('2','通報時段與值勤人員設定',`<div class="slot-grid">${SLOTS.map(p=>{const f=state.reports.find(r=>r.eventId===e.id&&r.slotId===p.id),thisDraft=p.id===s.id?d:state.drafts[e.id+'__'+p.id]||f||{peopleIds:[]};const selected=thisDraft.peopleIds||[];return `<div class="slot ${p.type} ${p.id===s.id?'selected':''}"><button class="choose-slot" data-slot="${p.id}" aria-pressed="${p.id===s.id}"><span class="slot-time">${p.time}</span><span class="slot-label">${p.label}</span></button><div class="duty-picker"><label class="hint">值勤人員（可多選）</label><details><summary>${selected.length?H(selected.map(id=>allStaff.find(x=>x.id===id)?.name||'(原人員已停用)').join('、')):'請選擇人員'}</summary><div class="picker-choices">${allStaff.length?allStaff.map(person=>`<label><input type="checkbox" data-staff-slot="${p.id}" data-person="${person.id}" ${selected.includes(person.id)?'checked':''} ${disabled()}>${H(person.name)}${person.job?'（'+H(person.job)+'）':''}</label>`).join(''):'<span class="none">本廠區尚未建立人員名單</span>'}</div></details></div>${p.attendance?'<div class="attention">需確認各單位出勤人數</div>':''}${p.patrol?`<div class="attention">應納入${p.patrol==='morning'?'上午':'下午'}巡查</div>`:''}${f?`<div class="saved">${f.status==='final'?'✓ 已完成通報':'○ 已存草稿'}</div>`:''}</div>`}).join('')}</div><div class="banner">選定時段後，在下方編輯該時段的Checklist及出勤人員；每個時段可選一人或多人，且不會自動沿用上一班。<b>00:00請用實際回報日期</b>。</div>`);
 const checks=panel('3',`值勤檢查項目（${s.time} ${s.label}）`,`${ownerBlock()}<div class="tabs">${['人員出勤','生產與環保','氣象與防汛','施工與巡查',...(s.id==='end'?['備勤結束最後確認']:[])].map((v,i)=>`<button class="tab ${state.checkTab===v||(!state.checkTab&&i===0)?'active':''}" data-check-tab="${H(v)}">${H(v)}</button>`).join('')}</div>${renderCheckTab(d,s)}<div class="footerbar"><button class="btn grey" data-action="draft-save" ${disabled()}>儲存本時段草稿</button><button class="btn" data-action="final-save" ${disabled()}>完成檢查並儲存通報</button></div>`);
 const preview=panel('4','通報內容預覽',`<div class="hint">依當前Checklist及人員狀況即時生成；尚未檢查的項目會顯示「未確認」，不會自動宣告正常。</div><div class="preview" id="reportPreview">${H(buildReport(d))}</div><div class="preview-buttons"><button class="btn secondary" data-action="preview">重新預覽</button><button class="btn green" data-action="copy-report" ${disabled()}>複製完整通報（供貼至LINE）</button></div>`,`sticky`);
 const incidents=panel('5','本次颱風異常事項（不受通報時段限制）',`${ownerBlock()}<div class="toolbar"><button class="btn red" data-action="open-incident" ${disabled()}>＋新增異常即時通報</button></div>${renderIncidentTable(e.id)}`);
 return `<div class="columns"><div>${header}${slots}${checks}${incidents}</div><div>${preview}${panel('i','原報告重點提醒',`<div class="time-note">08:00–09:00 與 00:00 特別確認各單位出勤人數及前一班人員狀況。</div><div class="time-note">12:00、16:00 回報應分別納入上午、下午實際巡查結果；天候不安全不得勉強巡查。</div><div class="time-note">發現異常應即時群組通報並主動聯絡主管、另附照片（照片不存本系統）。</div><div class="time-note">中、夜班依19:00、00:00、07:00回報；颱風備勤結束前另作最後確認。</div><button class="btn secondary" data-tab="rules">查看完整值勤規定</button>`)}</div></div>`;}
function renderCheckTab(d,s){const current=state.checkTab||'人員出勤';if(!['人員出勤','生產與環保','氣象與防汛','施工與巡查','備勤結束最後確認'].includes(current))state.checkTab='人員出勤';
 const group=CHECKS.find(g=>g.group===(state.checkTab||'人員出勤'));if(!group||group.onlyEnd&&s.id!=='end'){state.checkTab='人員出勤';return renderCheckTab(d,s);}
 const rows=group.rows.map(([id,title])=>{const selected=d.checks[id]||'pending';return `<div class="check-row"><b>${H(title)}</b><div class="status-set">${[['normal','正常'],['abnormal','異常'],['na','不適用'],['pending','未確認']].map(([k,v])=>`<label><input type="radio" name="status_${id}" value="${k}" data-status="${id}" ${k===selected?'checked':''} ${disabled()}>${v}</label>`).join('')}</div><input class="note-input" data-note="${id}" placeholder="備註；異常時必填說明" value="${H(d.notes[id]||'')}" ${disabled()}></div>`}).join('');
 if(group.group==='人員出勤')return `<div class="banner">${s.attendance?'此時段須逐單位確認應到／實到人數及前班狀況。':'此時段仍須完成各單位出勤與人員安全確認。'}</div><h3 class="subheading">各單位值勤人員出勤確認</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>單位</th><th>應到人數</th><th>實到人數</th><th>未正常出勤原因／備註</th><th>操作</th></tr></thead><tbody>${d.unitAttendance.map((r,i)=>`<tr><td><input data-unit="${i}" data-prop="unit" placeholder="請輸入單位" value="${H(r.unit)}" ${disabled()}></td><td><input type="number" min="0" step="1" data-unit="${i}" data-prop="expected" value="${H(r.expected)}" ${disabled()}></td><td><input type="number" min="0" step="1" data-unit="${i}" data-prop="actual" value="${H(r.actual)}" ${disabled()}></td><td><input data-unit="${i}" data-prop="note" placeholder="異常原因" value="${H(r.note)}" ${disabled()}></td><td><button class="btn red small" data-delete-unit="${i}" ${disabled()}>移除</button></td></tr>`).join('')}</tbody></table></div><div class="footerbar"><button class="btn secondary small" data-action="add-unit" ${disabled()}>＋新增單位</button></div><h3 class="subheading">人員確認 Checklist</h3>${rows}`;
 if(group.group==='氣象與防汛')return `<h3 class="subheading">氣象資料（手動輸入，不自動推測即時天氣）</h3><div class="datapair">${[['avg','平均風速 (m/s)'],['max','最大風速 (m/s)'],['direction','最大風速風向'],['rain','時雨量 (mm)'],['station','氣象測站'],['observationTime','觀測時間'],['conditions','天氣描述']].map(([id,label])=>`<div class="field"><label>${label}</label><input data-weather="${id}" value="${H(d.weather[id]||'')}" placeholder="未填" ${disabled()}></div>`).join('')}</div><h3 class="subheading">氣象與防汛 Checklist</h3>${rows}`;
 if(group.group==='施工與巡查')return `<h3 class="subheading">巡查紀錄（視安全條件執行）</h3><div class="toolbar"><div class="field"><label>本時段巡查結果${s.patrol?'（本時段需填）':''}</label><select data-patrol="result" ${disabled()}>${opts([['','尚未選擇'],['done','已入廠巡查'],['unsafe','因天候不佳，安全考量未入廠巡查'],['na','本時段不適用']],d.patrol.result)}</select></div><div class="field"><label>實際巡查時間</label><input data-patrol="time" type="text" placeholder="例如 11:20" value="${H(d.patrol.time)}" ${disabled()}></div><div class="field" style="flex:2"><label>巡查說明／未巡查原因</label><input data-patrol="note" placeholder="請填寫巡查結果或天候安全原因" value="${H(d.patrol.note)}" ${disabled()}></div></div><div class="banner warning">依原核定報告「視天氣狀況」上、下午各巡查一趟，颱風期間切勿為了完成打勾而冒險巡查。</div><h3 class="subheading">施工與巡查 Checklist</h3>${rows}`;
 if(group.onlyEnd)return `<div class="banner">備勤結束該班值勤人員，必須在下哨前再次確認並通報；無法改善的異常事項需持續跟催與交接。</div>${rows}`;
 return rows;
}
function renderIncidentTable(eventId){const items=state.incidents.filter(x=>x.eventId===eventId).sort((a,b)=>(b.at||'').localeCompare(a.at||''));if(!items.length)return `<p class="hint">目前無異常事項。請注意：此敘述只表示系統尚未登錄異常，不代表現場已完成檢查。</p>`;
 return `<div class="table-wrap"><table class="data-table"><thead><tr><th>發現時間</th><th>異常項目</th><th>說明／處置</th><th>照片及通報</th><th>追蹤</th><th>管理</th></tr></thead><tbody>${items.map(x=>`<tr><td>${H(x.at)}</td><td>${H(x.title)}</td><td>${H(x.details)}<hr>${H(x.action)}</td><td>群組：${x.groupNotified?'是':'否'}<br>主管：${x.supervisorContacted?'是':'否'}<br>照片：${x.photoAttached?'是':'否'}</td><td><span class="tag ${x.closed?'ok':'bad'}">${x.closed?'已結案':'未結案'}</span></td><td><button class="btn small secondary" data-edit-incident="${x.id}" ${disabled()}>編輯</button></td></tr>`).join('')}</tbody></table></div>`;}
function buildReport(d){const e=eventNow(),s=slotNow();if(!e)return '';const settings=state.settings.find(x=>x.id==='general')||{};const recipient=settings.recipient||'資總、副總及資深經理';const storedStaff=state.staff.filter(x=>(d.peopleIds||[]).includes(x.id));const people=storedStaff.map(x=>x.name+(x.job?'（'+x.job+'）':'')).join('、')||'未指定';
 const line=(id,name)=>`${name}：${stText[d.checks[id]||'pending']}${clean(d.notes[id])?'（'+clean(d.notes[id])+'）':''}`;
 const w=d.weather,number=(x,u)=>clean(x)?clean(x)+(u||''):'未填';const total=d.unitAttendance.filter(r=>clean(r.unit)).reduce((a,r)=>({ex:a.ex+(r.expected===''?0:Number(r.expected)),ac:a.ac+(r.actual===''?0:Number(r.actual))}),{ex:0,ac:0});const attend=d.unitAttendance.filter(x=>clean(x.unit)).map(r=>`  • ${r.unit}：應到${number(r.expected,'人')}、實到${number(r.actual,'人')}${r.note?'；'+r.note:''}`).join('\n')||'  • 尚未填寫各單位出勤人數';
 const incidents=state.incidents.filter(x=>x.eventId===e.id);const bad=incidents.length?incidents.map((x,i)=>`  ${i+1}. ${x.title}（${x.at}）：${x.details}；處置：${x.action||'尚未填'}；狀態：${x.closed?'已結案':'追蹤中'}；群組已報：${x.groupNotified?'是':'否'}，主管已聯繫：${x.supervisorContacted?'是':'否'}，照片已另附：${x.photoAttached?'是':'否'}`).join('\n'):'目前系統未登錄異常事項（仍以現場實際確認為準）';
 const checks=CHECKS.flatMap(x=>x.rows).filter(([id])=>s.id==='end'||!CHECKS.find(g=>g.onlyEnd)?.rows.some(([j])=>j===id));
 const patrol=d.patrol.result==='done'?'已入廠巡查':d.patrol.result==='unsafe'?'因天候不佳未入廠巡查':d.patrol.result==='na'?'不適用':'尚未確認';
 return `報告 ${recipient}：\n安衛處（${e.factory}）回報${e.name}，${d.reportDate} ${s.time}（${s.label}）值勤狀況，重點說明如下：\n\n一、人員出勤與值勤\n本時段值勤人員：${people}\n${attend}\n${d.unitAttendance.every(r=>r.expected!==''&&r.actual!==''&&clean(r.unit))&&d.unitAttendance.length?`  • 合計應到${total.ex}人、實到${total.ac}人`:'  • 人數合計：資料尚未完整'}\n${[line('attendance','各單位出勤'),line('previous','前一班人員'),line('transport','人員與交通安全')].join('\n')}\n\n二、生產與環保設備\n${[line('production','生產製程及設備'),line('pollution','污染防治設備'),line('cwms','CWMS監測'),line('cems','CEMS監測')].join('\n')}\n\n三、氣象及防汛狀況\n觀測：${number(w.observationTime)}；測站：${number(w.station)}\n平均風速：${number(w.avg,' m/s')}；最大風速：${number(w.max,' m/s')}；風向：${number(w.direction)}；時雨量：${number(w.rain,' mm')}\n天氣概況：${number(w.conditions)}\n${[line('storm','風雨現況'),line('floodInside','廠內積水'),line('floodOutside','廠外及道路積水'),line('buffer','雨水緩衝槽')].join('\n')}\n\n四、施工與巡查結果\n巡查：${patrol}${d.patrol.time?'（'+d.patrol.time+'）':''}${d.patrol.note?'；'+d.patrol.note:''}\n${[line('construction','施工現場'),line('highwork','30m以上高架作業'),line('electrical','電氣機具'),line('hazard','安全隱患')].join('\n')}\n${s.id==='end'?`\n五、備勤結束最後確認\n${CHECKS.find(x=>x.onlyEnd).rows.map(([id,n])=>line(id,n)).join('\n')}\n`:''}\n${s.id==='end'?'六':'五'}、異常與後續處理\n${bad}\n\n以上回報。\n安衛處（${e.factory}）｜${people}`;}
function validateDraft(d){const issues=[],s=slotNow();if(!d.peopleIds?.length)issues.push('至少選擇一位本時段值勤人員');if(!d.reportDate)issues.push('回報日期不可空白');
 for(const section of CHECKS){if(section.onlyEnd&&s.id!=='end')continue;for(const [id,title] of section.rows){const v=d.checks[id]||'pending';if(v==='pending')issues.push(`Checklist「${title}」尚未確認`);if(v==='abnormal'&&!clean(d.notes[id]))issues.push(`「${title}」異常須填備註`);}}
 if(s.attendance){if(!d.unitAttendance.length)issues.push('此時段須填各單位應到／實到人數');for(const r of d.unitAttendance){if(!clean(r.unit)||r.expected===''||r.actual===''||!Number.isInteger(Number(r.expected))||!Number.isInteger(Number(r.actual))||Number(r.expected)<0||Number(r.actual)<0)issues.push('各單位名稱、應到及實到非負整數必填');if(r.expected!==''&&r.actual!==''&&Number(r.expected)!==Number(r.actual)&&!clean(r.note))issues.push(`${r.unit||'單位'}出勤差異須填原因`);}
 const mismatch=d.unitAttendance.some(r=>r.expected!==''&&r.actual!==''&&Number(r.expected)!==Number(r.actual));if(mismatch&&d.checks.attendance==='normal')issues.push('有出勤人數差異，不可將各單位出勤勾選為正常');}
 if(s.patrol&&!d.patrol.result)issues.push('本時段須填上午／下午巡查結果');if(d.patrol.result==='unsafe'&&!clean(d.patrol.note))issues.push('因天候未巡查須填安全原因');
 if(d.patrol.result==='done'&&s.patrol&&!clean(d.patrol.time))issues.push('已巡查時請填實際巡查時間');
 for(const key of ['avg','max','direction','rain','observationTime'])if(!clean(d.weather[key]))issues.push(`氣象資料「${{avg:'平均風速',max:'最大風速',direction:'風向',rain:'時雨量',observationTime:'觀測時間'}[key]}」未填`);
 if(['avg','max','rain'].some(k=>d.weather[k]!==''&&(!Number.isFinite(Number(d.weather[k]))||Number(d.weather[k])<0)))issues.push('風速與雨量須為非負數值');
 return [...new Set(issues)];}
function renderEvents(){return panel('1','颱風事件管理',`${ownerBlock()}<div class="toolbar"><button class="btn" data-action="open-event" ${disabled()}>＋新增颱風事件</button><button class="btn secondary" data-action="excel">匯出完整 Excel</button></div><div class="banner">相同颱風可依不同廠區分別建事件。廠區包含麥寮、彰化、龍德、新港、台北；颱風事件與各時段通報均個別留存。</div>${state.events.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>颱風</th><th>廠區</th><th>事件日期</th><th>已存回報</th><th>操作</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${H(e.name)}</td><td>${H(e.factory)}</td><td>${H(e.date)}</td><td>${state.reports.filter(r=>r.eventId===e.id).length} / ${SLOTS.length}</td><td><button class="btn small secondary" data-open-event="${e.id}">開啟</button> <button class="btn small secondary" data-edit-event="${e.id}" ${disabled()}>修改</button> <button class="btn small red" data-delete-event="${e.id}" ${disabled()}>刪除</button></td></tr>`).join('')}</tbody></table></div>`:empty('尚未建立事件')}`);}
function renderPeople(){const filter=state.staffFilter||'全部';const people=state.staff.filter(p=>filter==='全部'||p.factory===filter);return panel('1','值勤人員基本資料管理',`${ownerBlock()}<div class="toolbar"><div class="field" style="max-width:250px"><label>篩選廠區</label><select data-global="staffFilter">${opts([['全部','全部廠區'],...FACTORIES.map(x=>[x,x])],filter)}</select></div><button class="btn" data-action="open-person" ${disabled()}>＋新增值勤人員</button></div><div class="hint">可新增、修改、停用人員；各時段下拉選單僅顯示所選廠區的啟用人員。既有通報內容另存文字快照，日後修改人員不會改寫已完成通報。</div>${people.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>姓名</th><th>廠區</th><th>單位</th><th>職稱／職務</th><th>電話</th><th>狀態</th><th>操作</th></tr></thead><tbody>${people.map(x=>`<tr><td>${H(x.name)}</td><td>${H(x.factory)}</td><td>${H(x.unit)}</td><td>${H(x.job)}</td><td>${H(x.phone)}</td><td><span class="tag ${x.active!==false?'ok':'warn'}">${x.active!==false?'啟用':'停用'}</span></td><td><button class="btn secondary small" data-edit-person="${x.id}" ${disabled()}>編輯</button> <button class="btn red small" data-delete-person="${x.id}" ${disabled()}>刪除</button></td></tr>`).join('')}</tbody></table></div>`:empty('此廠區目前沒有值勤人員資料')}`);}
function renderRules(){const section=SECTIONS.find(s=>s.id===state.sectionId)||SECTIONS[0],revision=state.rules.find(r=>r.id===section.id),notes=state.notes.filter(n=>n.sectionId===section.id).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')),revisions=state.revisions.filter(r=>r.sectionId===section.id).sort((a,b)=>(b.at||'').localeCompare(a.at||''));const href='assets/安全衛生處颱風出勤作業原則報告_原件.pdf';return panel('1','颱風值勤規定公告欄',`<div class="banner">本公告收錄原始PDF的所有章節、通報範例與主管手寫批示閱覽指引。<b>核定原文與增修訂公告分離保存。</b>手寫批示部分字跡不明者，請對照原始掃描，不能將推測轉錄視為核定內容。 <a href="${href}" target="_blank" rel="noopener">檢視原始核定PDF（3頁） ↗</a></div><div class="rule-layout"><div class="rules-list">${SECTIONS.map(s=>`<button data-rule-section="${s.id}" class="${s.id===section.id?'active':''}">${H(s.title)}<br><span class="hint">${H(s.page)}</span></button>`).join('')}</div><div><h3 class="subheading">${H(section.title)} <span class="tag">${H(section.page)}</span></h3><div class="hint">下方為原報告排版整理文字（掃描辨識有疑義時以原件為準）。</div><div class="rule-source">${H(section.text)}</div><h3 class="subheading">增修訂公告（獨立於核定原文）</h3>${revision?`<div class="banner">第 ${H(revision.version||1)} 版｜更新：${H(revision.updatedAt||'')}<br><span class="inline-data">${H(revision.text||'')}</span></div>`:'<p class="hint">此章目前尚無增修訂公告。</p>'}${isOwner()?`<div class="field"><label>編輯本章補充／修訂公告（不影響原PDF）</label><textarea id="ruleEdit" rows="5" placeholder="請輸入新增或修訂內容">${H(revision?.text||'')}</textarea></div><div class="footerbar"><button class="btn" data-action="save-rule">儲存修訂並保留版本歷程</button></div>`:ownerBlock()}<h3 class="subheading">備註管理</h3>${notes.map(n=>`<div class="comment"><div class="meta">${H(n.createdAt)}｜${H(n.author||'管理員')}</div><div class="inline-data">${H(n.text)}</div>${isOwner()?`<div class="actions"><button class="btn small secondary" data-edit-note="${n.id}">修改</button><button class="btn small red" data-delete-note="${n.id}">刪除</button></div>`:''}</div>`).join('')||'<p class="hint">尚無備註。</p>'}${isOwner()?`<div class="field form-row"><label>新增備註（可獨立增修訂）</label><textarea id="newNote" rows="3" placeholder="例如：值勤執行補充事項"></textarea></div><button class="btn secondary" data-action="add-note">＋新增備註</button>`:''}<h3 class="subheading">增修訂歷程（${revisions.length}筆）</h3>${revisions.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>日期</th><th>版本／動作</th><th>內容快照</th></tr></thead><tbody>${revisions.map(r=>`<tr><td>${H(r.at)}</td><td>${H(r.action)} ${H(r.version||'')}</td><td class="inline-data">${H(r.text).slice(0,300)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">尚無修訂紀錄。</p>'}</div></div>`);}
function renderHistory(){const history=state.reports.filter(r=>!state.historyFactory||r.factory===state.historyFactory||state.events.find(e=>e.id===r.eventId)?.factory===state.historyFactory).sort((a,b)=>(b.savedAt||'').localeCompare(a.savedAt||''));return panel('1','歷史通報與Excel紀錄',`<div class="toolbar"><div class="field" style="max-width:230px"><label>篩選廠區</label><select data-global="historyFactory">${opts([['','全部廠區'],...FACTORIES.map(x=>[x,x])],state.historyFactory||'')}</select></div><button class="btn green" data-action="excel">匯出完整 Excel（.xlsx）</button></div>${history.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>颱風／廠區</th><th>時段</th><th>回報日期</th><th>狀態</th><th>保存時間</th><th>操作</th></tr></thead><tbody>${history.map(r=>{const e=state.events.find(x=>x.id===r.eventId);return `<tr><td>${H(e?.name||'已刪事件')}／${H(e?.factory||'')}</td><td>${H(SLOTS.find(s=>s.id===r.slotId)?.time||r.slotId)}</td><td>${H(r.reportDate)}</td><td><span class="tag ${r.status==='final'?'ok':'warn'}">${r.status==='final'?'正式通報':'草稿'}</span></td><td>${H(r.savedAt)}</td><td><button class="btn secondary small" data-view-report="${r.id}">檢視文字</button> <button class="btn small secondary" data-load-report="${r.id}">回到Checklist</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('尚無儲存過的通報紀錄')}`);}
function renderSettings(){const s=state.settings.find(x=>x.id==='general')||{},units=s.units||{};return panel('1','系統設定',`<div class="banner warning">正式模式採用既有 EHS Firebase 登入，寫入權限只能屬於設定的管理員 UID，並須由 Firestore Rules 實際強制執行。登入頁面本身不能取代安全規則。</div><div class="field" style="max-width:460px"><label>通報稱謂（可由管理員修改）</label><input id="recipientSetting" value="${H(s.recipient||'資總、副總及資深經理')}" ${disabled()}></div><h3 class="subheading">各廠區預設出勤單位（選填）</h3><div class="hint">僅供新增時段Checklist時建立空白人數列，不代表當次實到。每行一個單位名稱，手動變更已存通報不會受影響。</div><div class="staff-grid">${FACTORIES.map(f=>`<div class="field"><label>${f}</label><textarea data-setting-units="${H(f)}" rows="4" placeholder="每行一個單位名稱" ${disabled()}>${H((units[f]||[]).join('\n'))}</textarea></div>`).join('')}</div><div class="footerbar"><button class="btn" data-action="save-settings" ${disabled()}>儲存系統設定</button></div><hr><p><b>運作模式：</b>${mode==='demo'?'本機示範（非正式資料）':'正式 Firebase Firestore'}</p><p><b>目前登入：</b>${H(currentUser()?.email||'未登入')}</p><p><b>設定管理員 UID：</b>${H(ownerUid||'示範模式')}</p>${mode==='firebase'?`<button class="btn secondary" data-action="logout">登出 Firebase</button>`:''}<p class="hint">更新程式不會自動刪除 Firestore 資料。請先閱讀部署說明再進行正式上線。</p>`);}
function dialog(content){const e=document.createElement('div');e.className='modal-shade';e.id='dialog';e.innerHTML=`<div class="modal" role="dialog" aria-modal="true">${content}</div>`;document.body.appendChild(e);e.addEventListener('click',event=>{if(event.target===e)e.remove();});}
