function modalEvent(id){const e=state.events.find(x=>x.id===id)||{id:'',name:'',factory:'麥寮',date:today()};dialog(`<h2>${id?'修改':'新增'}颱風事件</h2><form id="eventForm"><input type="hidden" name="id" value="${H(e.id)}"><div class="field form-row"><label>颱風名稱</label><input name="name" required value="${H(e.name)}" placeholder="例如：山陀兒颱風"></div><div class="field form-row"><label>廠區</label><select name="factory">${opts(FACTORIES.map(x=>[x,x]),e.factory)}</select></div><div class="field form-row"><label>事件日期</label><input name="date" type="date" required value="${H(e.date)}"></div><div class="actions"><button type="submit" class="btn">${id?'儲存修改':'建立事件'}</button><button type="button" class="btn secondary" data-action="close-dialog">取消</button></div></form>`);}
function modalPerson(id){const p=state.staff.find(x=>x.id===id)||{id:'',name:'',factory:eventNow()?.factory||'麥寮',unit:'',job:'',phone:'',active:true};dialog(`<h2>${id?'修改':'新增'}值勤人員</h2><form id="personForm"><input name="id" type="hidden" value="${H(p.id)}"><div class="field form-row"><label>姓名（必填）</label><input name="name" required value="${H(p.name)}"></div><div class="field form-row"><label>廠區</label><select name="factory">${opts(FACTORIES.map(x=>[x,x]),p.factory)}</select></div><div class="field form-row"><label>單位</label><input name="unit" value="${H(p.unit)}"></div><div class="field form-row"><label>職務／職稱</label><input name="job" value="${H(p.job)}"></div><div class="field form-row"><label>聯絡電話（選填）</label><input name="phone" value="${H(p.phone)}"></div><label class="checkboxline form-row"><input type="checkbox" name="active" ${p.active!==false?'checked':''}> 啟用（顯示於該廠區值勤選單）</label><div class="actions"><button class="btn" type="submit">儲存</button><button class="btn secondary" type="button" data-action="close-dialog">取消</button></div></form>`);}
function modalIncident(id){const inc=state.incidents.find(x=>x.id===id)||{id:'',eventId:state.eventId,at:now(),title:'',details:'',action:'',groupNotified:false,supervisorContacted:false,photoAttached:false,closed:false};dialog(`<h2>${id?'修改':'新增'}異常即時通報</h2><div class="banner warning">異常發生應即時於群組回報並主動聯絡主管；本系統不會自動發送LINE，亦不儲存照片。</div><form id="incidentForm"><input type="hidden" name="id" value="${H(inc.id)}"><div class="field form-row"><label>發現時間</label><input name="at" value="${H(inc.at)}" required></div><div class="field form-row"><label>異常項目</label><input name="title" value="${H(inc.title)}" required></div><div class="field form-row"><label>異常情況描述</label><textarea name="details" rows="3" required>${H(inc.details)}</textarea></div><div class="field form-row"><label>處置措施／後續追蹤</label><textarea name="action" rows="3">${H(inc.action)}</textarea></div><div class="form-row"><label class="checkboxline"><input name="groupNotified" type="checkbox" ${inc.groupNotified?'checked':''}>已即時群組通報</label></div><div class="form-row"><label class="checkboxline"><input name="supervisorContacted" type="checkbox" ${inc.supervisorContacted?'checked':''}>已主動聯絡主管</label></div><div class="form-row"><label class="checkboxline"><input name="photoAttached" type="checkbox" ${inc.photoAttached?'checked':''}>已在外部群組附照片／影片</label></div><div class="form-row"><label class="checkboxline"><input name="closed" type="checkbox" ${inc.closed?'checked':''}>本事件已完成改善／結案</label></div><div class="actions"><button type="submit" class="btn">儲存異常紀錄</button>${id?`<button type="button" class="btn red" data-delete-incident="${id}">刪除本異常</button>`:''}<button type="button" class="btn secondary" data-action="close-dialog">取消</button></div></form>`);}
function modalText(title,text){dialog(`<h2>${H(title)}</h2><div class="preview" style="max-height:65vh">${H(text)}</div><div class="actions form-row"><button class="btn green" data-copy-text="${H(text)}">複製此筆原始通報</button><button class="btn secondary" data-action="close-dialog">關閉</button></div>`);}
function formValues(form){const fd=new FormData(form),obj=Object.fromEntries(fd.entries());for(const c of ['active','groupNotified','supervisorContacted','photoAttached','closed'])if(form.elements.namedItem(c))obj[c]=Boolean(form.elements.namedItem(c).checked);return obj;}
async function guarded(f){if(!isOwner()){toast('此帳號為唯讀，無法修改','error');return;}try{await f();}catch(e){console.error(e);toast('操作失敗：'+e.message,'error');}}
async function saveReport(final=false){await guarded(async()=>{const e=eventNow(),d=draft();if(!e)throw Error('請先建立事件');if(final){const errs=validateDraft(d);if(errs.length){dialog(`<h2>無法完成通報</h2><p>尚有 ${errs.length} 項需要修正：</p><div class="preview" style="max-height:45vh">${H(errs.map((x,i)=>`${i+1}. ${x}`).join('\n'))}</div><button class="btn secondary form-row" data-action="close-dialog">返回修正</button>`);return;}}
 const stored=state.reports.find(x=>x.id===d.id);if(stored?.status==='final'&&!final&&!confirm('這筆已完成通報，重新儲存草稿會改為草稿狀態，確定嗎？'))return;
 const value=structuredClone(d);value.status=final?'final':'draft';value.savedAt=now();value.factory=e.factory;value.name=e.name;value.personnelSnapshot=value.peopleIds.map(id=>state.staff.find(p=>p.id===id)).filter(Boolean).map(p=>({name:p.name,unit:p.unit,job:p.job,id:p.id}));value.reportText=buildReport(d);await saveDoc('reports',value);state.reports=state.reports.filter(x=>x.id!==value.id).concat(value);state.drafts[draftKey()]=structuredClone(value);toast(final?'正式通報已保存（請自行複製並發送LINE）':'草稿已保存');render();});}
function saveFormToDraft(el){if(!state.eventId||!isOwner())return;const d=draft();if(el.dataset.field)d[el.dataset.field]=el.value;
 if(el.dataset.status){d.checks[el.dataset.status]=el.value;}
 if(el.dataset.note)d.notes[el.dataset.note]=el.value;
 if(el.dataset.weather)d.weather[el.dataset.weather]=el.value;
 if(el.dataset.patrol)d.patrol[el.dataset.patrol]=el.value;
 if(el.dataset.unit!==undefined){const row=d.unitAttendance[Number(el.dataset.unit)];if(row)row[el.dataset.prop]=el.value;}
 const preview=$('#reportPreview');if(preview)preview.textContent=buildReport(d);
}
async function exportExcel(){try{const all=state.events.map(e=>[e.id,e.name,e.factory,e.date]),r=state.reports,inc=state.incidents;const filtered=state.historyFactory?state.events.filter(e=>e.factory===state.historyFactory):state.events;const eventIds=new Set(filtered.map(e=>e.id));const tables=[{name:'颱風事件',rows:[['事件ID','颱風名稱','廠區','事件日期'],...filtered.map(e=>[e.id,e.name,e.factory,e.date])]},{name:'各時段回報',rows:[['事件','廠區','回報日期','時段','狀態','值勤人員','儲存時間','完整通報內容'],...r.filter(x=>eventIds.has(x.eventId)).map(x=>[x.name,x.factory,x.reportDate,SLOTS.find(s=>s.id===x.slotId)?.time||x.slotId,x.status==='final'?'正式':'草稿',(x.personnelSnapshot||[]).map(p=>p.name).join('、'),x.savedAt,x.reportText])]},{name:'Checklist',rows:[['颱風事件ID','回報日期','時段','檢查項目','結果','備註'],...r.filter(x=>eventIds.has(x.eventId)).flatMap(x=>CHECKS.flatMap(c=>c.rows.map(([id,label])=>[x.eventId,x.reportDate,x.slotId,label,stText[x.checks?.[id]||'pending'],x.notes?.[id]||''])))]},{name:'出勤人數',rows:[['事件ID','日期','時段','單位','應到','實到','備註'],...r.filter(x=>eventIds.has(x.eventId)).flatMap(x=>(x.unitAttendance||[]).map(u=>[x.eventId,x.reportDate,x.slotId,u.unit,u.expected,u.actual,u.note]))]},{name:'異常事件',rows:[['事件ID','時間','異常項目','說明','處置','群組已通報','主管已聯絡','外部照片已附','已結案'],...inc.filter(x=>eventIds.has(x.eventId)).map(x=>[x.eventId,x.at,x.title,x.details,x.action,x.groupNotified?'是':'否',x.supervisorContacted?'是':'否',x.photoAttached?'是':'否',x.closed?'是':'否'])]},{name:'值勤人員名單',rows:[['姓名','廠區','單位','職務','電話','啟用'],...state.staff.filter(p=>!state.historyFactory||p.factory===state.historyFactory).map(p=>[p.name,p.factory,p.unit,p.job,p.phone,p.active!==false?'是':'否'])]}];downloadBlob(workbook(tables),`安衛處颱風值勤紀錄_${today()}.xlsx`);toast('已產生 Excel 活頁簿');}catch(e){toast('Excel 匯出失敗：'+e.message,'error');}}
// 以事件委派方式綁定控制項，切換畫面後仍維持操作。
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-tab],[data-action],[data-slot],[data-check-tab],[data-rule-section],[data-edit-person],[data-delete-person],[data-edit-event],[data-delete-event],[data-open-event],[data-edit-incident],[data-delete-incident],[data-view-report],[data-load-report],[data-delete-unit],[data-edit-note],[data-delete-note],[data-copy-text]');if(!b)return;
 if(b.dataset.tab){setTab(b.dataset.tab);return;}
 if(b.dataset.slot){state.slotId=b.dataset.slot;state.checkTab='人員出勤';render();return;}
 if(b.dataset.checkTab){state.checkTab=b.dataset.checkTab;render();return;}
 if(b.dataset.ruleSection){state.sectionId=b.dataset.ruleSection;render();return;}
 if(b.dataset.openEvent){state.eventId=b.dataset.openEvent;state.slotId='08';setTab('duty');return;}
 if(b.dataset.editEvent){modalEvent(b.dataset.editEvent);return;}
 if(b.dataset.editPerson){modalPerson(b.dataset.editPerson);return;}
 if(b.dataset.editIncident){modalIncident(b.dataset.editIncident);return;}
 if(b.dataset.viewReport){const r=state.reports.find(x=>x.id===b.dataset.viewReport);if(r)modalText(`${r.name} ${SLOTS.find(s=>s.id===r.slotId)?.time||''}－原始儲存通報`,r.reportText||'無報告快照');return;}
 if(b.dataset.loadReport){const r=state.reports.find(x=>x.id===b.dataset.loadReport);if(r){state.eventId=r.eventId;state.slotId=r.slotId;delete state.drafts[draftKey()];setTab('duty');}return;}
 if(b.dataset.deleteUnit!==undefined){await guarded(async()=>{const rows=draft().unitAttendance;if(rows.length<=1){toast('請至少保留一個單位輸入列','error');return;}rows.splice(Number(b.dataset.deleteUnit),1);draft().status='draft';render();});return;}
 if(b.dataset.editNote){const item=state.notes.find(n=>n.id===b.dataset.editNote);if(!item)return;dialog(`<h2>修改本章備註</h2><form id="editNoteForm"><input type="hidden" name="id" value="${H(item.id)}"><textarea class="plain-input" name="text" rows="6" required>${H(item.text)}</textarea><div class="actions form-row"><button class="btn" type="submit">儲存備註</button><button type="button" class="btn secondary" data-action="close-dialog">取消</button></div></form>`);return;}
 if(b.dataset.deleteNote){await guarded(async()=>{if(!confirm('確定刪除此筆備註？修訂歷程仍會保留刪除記錄。'))return;const n=state.notes.find(x=>x.id===b.dataset.deleteNote);await saveDoc('revisions',{id:makeId(),sectionId:n.sectionId,at:now(),action:'刪除備註',text:n.text,version:''});await deleteDoc('notes',n.id);toast('備註已刪除，保留修訂紀錄');await refresh();});return;}
 if(b.dataset.deletePerson){await guarded(async()=>{const id=b.dataset.deletePerson;const inUse=state.reports.some(r=>r.peopleIds?.includes(id));if(inUse){toast('此人員已有值勤紀錄，請改為「停用」以保留歷史關聯','error');return;}if(!confirm('確定刪除此人員？'))return;await deleteDoc('staff',id);for(const key of Object.keys(state.drafts))state.drafts[key].peopleIds=state.drafts[key].peopleIds?.filter(x=>x!==id)||[];toast('已刪除');await refresh();});return;}
 if(b.dataset.deleteEvent){await guarded(async()=>{const id=b.dataset.deleteEvent;const r=state.reports.filter(x=>x.eventId===id),incc=state.incidents.filter(x=>x.eventId===id);if(!confirm(`確定永久刪除這筆颱風事件、其 ${r.length} 筆通報與 ${incc.length} 筆異常？此操作不可還原。建議先匯出Excel備份。`))return;for(const x of r)await deleteDoc('reports',x.id);for(const x of incc)await deleteDoc('incidents',x.id);await deleteDoc('events',id);state.eventId='';Object.keys(state.drafts).filter(k=>k.startsWith(id+'__')).forEach(k=>delete state.drafts[k]);toast('事件已刪除');await refresh();});return;}
 if(b.dataset.deleteIncident){await guarded(async()=>{if(!confirm('確定刪除此異常紀錄？'))return;await deleteDoc('incidents',b.dataset.deleteIncident);closeDialog();await refresh();});return;}
 if(b.dataset.copyText!==undefined){try{await navigator.clipboard.writeText(b.dataset.copyText);toast('已複製原始通報內容');}catch(e){toast('複製失敗，請手動選取內容','error');}return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='close-dialog'){closeDialog();return;}
 if(action==='refresh'){await refresh();return;}
 if(action==='open-event'){modalEvent();return;}
 if(action==='open-person'){modalPerson();return;}
 if(action==='open-incident'){if(!eventNow()){toast('請先建立事件','error');return;}modalIncident();return;}
 if(action==='add-unit'){await guarded(async()=>{draft().unitAttendance.push({id:makeId(),unit:'',expected:'',actual:'',note:''});draft().status='draft';render();});return;}
 if(action==='draft-save'){await saveReport(false);return;}
 if(action==='final-save'){await saveReport(true);return;}
 if(action==='preview'){const p=$('#reportPreview');if(p)p.textContent=buildReport(draft());toast('預覽已更新（未確認項目仍會如實呈現）');return;}
 if(action==='copy-report'){const d=draft(),problems=validateDraft(d),saved=reportStored();if(problems.length){toast(`尚有 ${problems.length} 項未完成，禁止複製作為正式通報。請先完成Checklist。`,'error');return;}if(!saved||saved.status!=='final'||saved.reportText!==buildReport(d)){toast('請先點選「完成檢查並儲存通報」，以確保複製的是已存正式版','error');return;}
 try{await navigator.clipboard.writeText(saved.reportText);toast('已複製正式通報文字，請自行貼至LINE並檢查發送對象');}catch(e){toast('瀏覽器不支援自動複製，請手動選取通報文字','error');}return;}
 if(action==='excel'){exportExcel();return;}
 if(action==='save-rule'){await guarded(async()=>{const text=clean($('#ruleEdit')?.value),old=state.rules.find(x=>x.id===state.sectionId);if(old?.text===text){toast('未偵測到修訂內容變化');return;}const v=(old?.version||0)+1;await saveDoc('rules',{id:state.sectionId,text,version:v,updatedAt:now(),updatedBy:currentUser()?.uid||'DEMO'});await saveDoc('revisions',{id:makeId(),sectionId:state.sectionId,at:now(),action:'修訂公告',version:v,text,previousText:old?.text||''});toast('修訂已儲存，原始核定內容不受影響');await refresh();});return;}
 if(action==='add-note'){await guarded(async()=>{const text=clean($('#newNote')?.value);if(!text)throw Error('備註不得空白');const id=makeId();await saveDoc('notes',{id,sectionId:state.sectionId,text,createdAt:now(),author:currentUser()?.email||'管理員'});await saveDoc('revisions',{id:makeId(),sectionId:state.sectionId,at:now(),action:'新增備註',text,version:''});toast('備註已新增');await refresh();});return;}
 if(action==='save-settings'){await guarded(async()=>{const units={};document.querySelectorAll('[data-setting-units]').forEach(x=>units[x.dataset.settingUnits]=x.value.split(/\r?\n/).map(clean).filter(Boolean));await saveDoc('settings',{id:'general',recipient:clean($('#recipientSetting').value)||'資總、副總及資深經理',units});toast('設定已儲存');await refresh();});return;}
 if(action==='logout'){await signOut();return;}
});
document.addEventListener('input',ev=>{const e=ev.target;if(e.matches('[data-field],[data-status],[data-note],[data-weather],[data-patrol],[data-unit]'))saveFormToDraft(e);});
document.addEventListener('change',ev=>{const e=ev.target;
 if(e.dataset.global==='event'){state.eventId=e.value;state.slotId='08';state.checkTab='人員出勤';render();return;}
 if(e.dataset.global==='staffFilter'){state.staffFilter=e.value;render();return;}
 if(e.dataset.global==='historyFactory'){state.historyFactory=e.value;render();return;}
 if(e.dataset.staffSlot){if(!isOwner())return;const old=state.slotId;state.slotId=e.dataset.staffSlot;const d=draft();const id=e.dataset.person;if(e.checked&&!d.peopleIds.includes(id))d.peopleIds.push(id);if(!e.checked)d.peopleIds=d.peopleIds.filter(x=>x!==id);d.status='draft';state.slotId=old;render();return;}
 if(e.matches('[data-field],[data-status],[data-note],[data-weather],[data-patrol],[data-unit]'))saveFormToDraft(e);
});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!['eventForm','personForm','incidentForm','editNoteForm','loginForm'].includes(f.id))return;ev.preventDefault();if(f.id==='loginForm'){try{await signIn(f.elements.email.value,f.elements.password.value);toast('登入成功');}catch(e){toast('登入失敗：'+e.message,'error');}return;}
 await guarded(async()=>{const v=formValues(f);
 if(f.id==='eventForm'){if(!clean(v.name))throw Error('請填寫颱風名稱');const old=state.events.find(e=>e.id===v.id);if(old&&old.factory!==v.factory&&state.reports.some(r=>r.eventId===v.id))throw Error('此事件已經有時段通報，為保護歷史資料不可更改廠區；請另建事件。');const id=v.id||makeId();await saveDoc('events',{id,name:clean(v.name),factory:v.factory,date:v.date,createdAt:old?.createdAt||now()});state.eventId=id;state.slotId='08';state.drafts={};state.tab='duty';}
 if(f.id==='personForm'){if(!clean(v.name))throw Error('姓名不可空白');const old=state.staff.find(x=>x.id===v.id);if(old&&old.factory!==v.factory&&state.reports.some(r=>r.peopleIds?.includes(v.id)))throw Error('此人員已被歷史通報使用，不能直接改變所屬廠區；請停用原人員並在新廠區另建。');await saveDoc('staff',{id:v.id||makeId(),name:clean(v.name),factory:v.factory,unit:clean(v.unit),job:clean(v.job),phone:clean(v.phone),active:v.active});}
 if(f.id==='incidentForm'){if(!clean(v.title)||!clean(v.details))throw Error('異常標題及說明為必填');const prev=state.incidents.find(x=>x.id===v.id);await saveDoc('incidents',{id:v.id||makeId(),eventId:prev?.eventId||state.eventId,at:clean(v.at),title:clean(v.title),details:clean(v.details),action:clean(v.action),groupNotified:v.groupNotified,supervisorContacted:v.supervisorContacted,photoAttached:v.photoAttached,closed:v.closed});}
 if(f.id==='editNoteForm'){if(!clean(v.text))throw Error('備註不可空白');const old=state.notes.find(x=>x.id===v.id);await saveDoc('notes',{...old,text:clean(v.text),updatedAt:now()});await saveDoc('revisions',{id:makeId(),sectionId:old.sectionId,at:now(),action:'修改備註',text:clean(v.text),previousText:old.text,version:''});}
 closeDialog();toast('資料已儲存');await refresh();});});
$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
function showLogin(){userLabel();$('#main').innerHTML=`<div class="panel" style="max-width:550px;margin:5vh auto"><h2>登入 EHS Firebase 帳號</h2><p>如已在 EHS Portal 使用同一 Firebase 專案登入，系統可能自動承接登入狀態；若未登入，可使用現有 Email／Password 帳號登入。</p><form id="loginForm"><div class="field form-row"><label>Email</label><input name="email" type="email" required autocomplete="username"></div><div class="field form-row"><label>密碼</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn" type="submit">登入</button></form><div class="banner warning">請勿在 config.js、GitHub 或任何程式碼內填寫帳號密碼。既有 EHS Portal 若使用 Google 登入，請先登入入口站並確認同源登入狀態；本系統的 Email 登入僅使用同專案已存在的帳號。</div></div>`;}
async function boot(){try{await init(async user=>{if(mode==='firebase'&&!user){showLogin();return;}await refresh();});}catch(e){mainError(e);}}
boot();
function renderEvents(){return panel('1','颱風事件管理',`${ownerBlock()}<div class="toolbar"><button class="btn" data-action="open-event" ${disabled()}>＋新增颱風事件／廠區</button></div><div class="hint">同一颱風不同廠區分開建檔；台北為追加廠區，值勤員額請自行依實際核定規定設定。</div><div class="table-wrap"><table class="data-table"><thead><tr><th>颱風</th><th>廠區</th><th>日期</th><th>管理</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${H(e.name)}</td><td>${H(e.factory)}</td><td>${H(e.date)}</td><td><button class="btn small secondary" data-open-record="${e.id}">進入值勤</button> <button class="btn small" data-edit-event="${e.id}" ${disabled()}>修改</button><button class="btn small red" data-delete-event="${e.id}" ${disabled()}>刪除</button></td></tr>`).join('')}</tbody></table></div>`);}
function renderPeople(){return panel('1','值勤人員基本資料',`${ownerBlock()}<div class="toolbar"><button class="btn" data-action="add-staff" ${disabled()}>＋新增人員</button></div><div class="banner">每一廠區的名單獨立，建立後可重複使用。可停用人員；歷史通報將保留當時通報內容。</div><div class="table-wrap"><table class="data-table"><thead><tr><th>廠區</th><th>姓名</th><th>單位</th><th>職稱／業務</th><th>電話</th><th>狀態</th><th>操作</th></tr></thead><tbody>${state.staff.map(x=>`<tr><td>${H(x.factory)}</td><td>${H(x.name)}</td><td>${H(x.unit)}</td><td>${H(x.job)}</td><td>${H(x.phone)}</td><td>${x.active===false?'停用':'啟用'}</td><td><button class="btn small secondary" data-edit-staff="${x.id}" ${disabled()}>修改</button></td></tr>`).join('')}</tbody></table></div>`);}
function renderRules(){const section=SECTIONS.find(x=>x.id===state.sectionId)||SECTIONS[0],override=state.rules.find(x=>x.id===section.id),notes=state.notes.filter(x=>x.sectionId===section.id);return panel('1','颱風值勤規定公告欄',`<div class="banner">以2025/11/12核定掃描報告為依據；文字整理僅為便於查詢。原始PDF含手寫批示，完整保留，不因後續增修訂而覆蓋。補充修訂不等於自動取得主管核定。</div><div class="toolbar"><a href="assets/安全衛生處颱風出勤作業原則報告_原件.pdf" target="_blank" rel="noopener" class="btn secondary">檢視原始核定PDF（3頁）</a></div><div class="rule-layout"><div class="rules-list">${SECTIONS.map(x=>`<button class="${x.id===section.id?'active':''}" data-section="${x.id}">${H(x.title)}</button>`).join('')}</div><div><h3>${H(section.title)} <span class="pill">${H(section.page)}</span></h3><div class="rule-source">${H(override?.text||section.text)}</div>${override?`<div class="banner warning">這是後續修訂版（${H(override.updatedAt||'')}），原始規定請核對PDF；修訂原因：${H(override.reason||'未填')}</div>`:''}${isOwner()?`<div class="footerbar"><button class="btn secondary" data-action="edit-rule">修訂本章公告文字</button><button class="btn" data-action="add-note">＋新增本章備註</button></div>`:''}<h3 class="subheading">本章備註（可增修訂）</h3>${notes.map(n=>`<div class="comment"><div class="meta">${H(n.author||'管理員')}　${H(n.updatedAt||n.createdAt)}</div><div class="inline-data">${H(n.text)}</div>${isOwner()?`<div class="actions"><button class="btn small secondary" data-edit-note="${n.id}">修改</button><button class="btn small red" data-delete-note="${n.id}">刪除</button></div>`:''}</div>`).join('')||empty('尚無備註')}<h3 class="subheading">本章增修訂紀錄</h3>${state.revisions.filter(x=>x.sectionId===section.id).map(r=>`<div class="comment"><div class="meta">${H(r.at)}　${H(r.reason||'修訂')}</div><details><summary>查看修訂前文字</summary><div class="rule-source">${H(r.before)}</div></details></div>`).join('')||empty('尚無修訂紀錄')}</div></div>`);}
function renderHistory(){return panel('1','歷史通報紀錄',`<div class="toolbar"><button class="btn secondary" data-action="export">匯出Excel值勤紀錄</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>颱風／廠區</th><th>通報日期</th><th>時段</th><th>狀態</th><th>儲存時間</th><th>內容</th></tr></thead><tbody>${state.reports.map(r=>{const e=state.events.find(x=>x.id===r.eventId),s=SLOTS.find(x=>x.id===r.slotId);return `<tr><td>${H(e?.name||r.eventId)}／${H(e?.factory||'')}</td><td>${H(r.reportDate)}</td><td>${H(s?.time||r.slotId)}</td><td>${r.status==='final'?'已完成':'草稿'}</td><td>${H(r.savedAt)}</td><td><button class="btn small secondary" data-view-report="${r.id}">查看／複製</button></td></tr>`}).join('')}</tbody></table></div>`);}
function renderSettings(){const s=state.settings.find(x=>x.id==='general')||{};return panel('1','系統設定',`${ownerBlock()}<form id="settingsForm"><div class="field"><label>通報抬頭收件人</label><input name="recipient" value="${H(s.recipient||'資總、副總及資深經理')}" ${disabled()}></div><h3 class="subheading">各廠區出勤檢核單位（每行一個，作為新增Checklist的預設單位）</h3>${FACTORIES.map(f=>`<div class="field form-row"><label>${f}</label><textarea name="units_${f}" ${disabled()}>${H((s.units?.[f]||[]).join('\n'))}</textarea></div>`).join('')}<button class="btn" type="submit" ${disabled()}>儲存設定</button></form><div class="banner warning">僅指定管理員可修改。實際存取權必須由Firestore Rules限制，前端唯讀無法取代雲端安全規則。</div>`);}
const modal=(html)=>{document.querySelector('.modal-shade')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-shade"><div class="modal"><button class="btn secondary small" style="float:right" data-action="close-modal">關閉</button>${html}</div></div>`)};
function eventModal(obj={}){modal(`<h2>${obj.id?'修改':'新增'}颱風事件</h2><form id="eventForm"><input type="hidden" name="id" value="${H(obj.id||'')}"><div class="field form-row"><label>颱風名稱</label><input name="name" required value="${H(obj.name||'')}"></div><div class="field form-row"><label>廠區</label><select name="factory">${opts(FACTORIES.map(x=>[x,x]),obj.factory||FACTORIES[0])}</select></div><div class="field form-row"><label>開始日期</label><input type="date" required name="date" value="${H(obj.date||today())}"></div><button class="btn" type="submit">儲存</button></form>`)}
function staffModal(obj={}){modal(`<h2>${obj.id?'修改':'新增'}值勤人員</h2><form id="staffForm"><input type="hidden" name="id" value="${H(obj.id||'')}">${[['name','姓名'],['unit','單位'],['job','職稱／業務'],['phone','聯絡電話']].map(([id,label])=>`<div class="field form-row"><label>${label}</label><input name="${id}" ${id==='name'?'required':''} value="${H(obj[id]||'')}"></div>`).join('')}<div class="field form-row"><label>所屬廠區</label><select name="factory">${opts(FACTORIES.map(x=>[x,x]),obj.factory||FACTORIES[0])}</select></div><label class="checkboxline"><input type="checkbox" name="active" ${obj.active!==false?'checked':''}>啟用</label><div class="footerbar"><button class="btn" type="submit">儲存人員</button></div></form>`)}
function incidentModal(obj={}){modal(`<h2>${obj.id?'修改':'新增'}異常事件</h2><div class="banner warning">異常應立即通報群組並主動聯繫主管；若需附照片請另於LINE群組提供，本系統不會儲存附件。</div><form id="incidentForm"><input type="hidden" name="id" value="${H(obj.id||'')}">${[['at','發現時間',now()],['title','異常項目',''],['details','狀況說明',''],['action','處置措施／追蹤','']].map(([k,t,def])=>`<div class="field form-row"><label>${t}</label>${k==='details'||k==='action'?`<textarea name="${k}">${H(obj[k]||def)}</textarea>`:`<input name="${k}" ${k==='title'?'required':''} value="${H(obj[k]||def)}">`}</div>`).join('')}${[['groupNotified','已於群組即時回報'],['supervisorContacted','已主動聯繫主管'],['photoAttached','已在群組另附照片'],['closed','已完成改善結案']].map(([k,t])=>`<div class="form-row"><label class="checkboxline"><input type="checkbox" name="${k}" ${obj[k]?'checked':''}>${t}</label></div>`).join('')}<button class="btn" type="submit">儲存異常紀錄</button></form>`)}
function ruleModal(){const s=SECTIONS.find(x=>x.id===state.sectionId),r=state.rules.find(x=>x.id===s.id);modal(`<h2>修訂公告：${H(s.title)}</h2><div class="banner warning">僅修改公告顯示文字。原核定PDF保持不變，並保存修訂前內容。</div><form id="ruleForm"><div class="field"><label>修訂原因</label><input name="reason" required></div><div class="field form-row"><label>公告文字</label><textarea name="text" style="min-height:310px" required>${H(r?.text||s.text)}</textarea></div><button class="btn">保存修訂紀錄</button></form>`)}
function noteModal(obj={}){modal(`<h2>${obj.id?'修改':'新增'}公告備註</h2><form id="noteForm"><input type="hidden" name="id" value="${H(obj.id||'')}"><div class="field"><label>備註文字</label><textarea name="text" required style="min-height:170px">${H(obj.text||'')}</textarea></div><button class="btn">儲存備註</button></form>`)}
async function saveDraft(final){const d=draft();if(final){const errors=validateDraft(d);if(errors.length){alert('無法完成通報：\n• '+errors.slice(0,20).join('\n• ')+(errors.length>20?'\n…':''));return;}}const record=structuredClone(d);record.status=final?'final':'draft';record.savedAt=now();record.reportText=buildReport(record);record.peopleSnapshot=state.staff.filter(p=>record.peopleIds.includes(p.id)).map(p=>({name:p.name,job:p.job,factory:p.factory}));await saveDoc('reports',record);state.drafts[draftKey()]=record;toast(final?'本時段完整紀錄已儲存':'草稿已儲存');await refresh();}
async function copyText(str){try{await navigator.clipboard.writeText(str);toast('已複製文字，可貼至LINE群組；貼上並不代表已送出。');}catch(e){modal(`<h2>請手動複製</h2><textarea class="plain-input" style="min-height:340px">${H(str)}</textarea>`);}}
function exportExcel(){const rows=[['颱風','廠區','回報日期','時段','狀態','儲存時間','值勤人員','通報全文']];state.reports.forEach(r=>{const e=state.events.find(x=>x.id===r.eventId),s=SLOTS.find(x=>x.id===r.slotId);rows.push([e?.name||'',e?.factory||'',r.reportDate,s?.time||r.slotId,r.status,r.savedAt,(r.peopleSnapshot||[]).map(x=>x.name).join('、'),r.reportText||'']);});const incidentRows=[['事件ID','發現時間','異常項目','狀況','處置','群組回報','主管已聯絡','照片另附','已結案'],...state.incidents.map(x=>[x.eventId,x.at,x.title,x.details,x.action,x.groupNotified?'是':'否',x.supervisorContacted?'是':'否',x.photoAttached?'是':'否',x.closed?'是':'否'])];downloadBlob(workbook([{name:'值勤通報',rows},{name:'異常事件',rows:incidentRows}]),`颱風值勤紀錄_${today()}.xlsx`);}
function updatePreview(){const p=$('#reportPreview');if(p)p.textContent=buildReport(draft());}
async function handleAction(target){const a=target.dataset.action;try{if(a==='refresh')return refresh();if(a==='close-modal'){document.querySelector('.modal-shade')?.remove();return;}if(a==='open-event')return eventModal();if(a==='add-staff')return staffModal();if(a==='open-incident')return incidentModal();if(a==='edit-rule')return ruleModal();if(a==='add-note')return noteModal();if(a==='add-unit'){draft().unitAttendance.push({id:makeId(),unit:'',expected:'',actual:'',note:''});render();return;}if(a==='preview'){updatePreview();return;}if(a==='copy-report')return copyText(buildReport(draft()));if(a==='draft-save')return saveDraft(false);if(a==='final-save')return saveDraft(true);if(a==='export')return exportExcel();}catch(err){toast(err.message,'error');}}
document.addEventListener('click',async ev=>{const t=ev.target.closest('[data-action],[data-tab],[data-slot],[data-check-tab],[data-section],[data-open-record],[data-edit-event],[data-delete-event],[data-edit-staff],[data-edit-incident],[data-edit-note],[data-delete-note],[data-delete-unit],[data-view-report]');if(!t)return;try{if(t.dataset.action)return handleAction(t);if(t.dataset.tab)return setTab(t.dataset.tab);if(t.dataset.slot){state.slotId=t.dataset.slot;state.checkTab='人員出勤';render();return;}if(t.dataset.checkTab){state.checkTab=t.dataset.checkTab;render();return;}if(t.dataset.section){state.sectionId=t.dataset.section;render();return;}if(t.dataset.openRecord){state.eventId=t.dataset.openRecord;state.tab='duty';render();return;}if(t.dataset.editEvent)return eventModal(state.events.find(x=>x.id===t.dataset.editEvent));if(t.dataset.editStaff)return staffModal(state.staff.find(x=>x.id===t.dataset.editStaff));if(t.dataset.editIncident)return incidentModal(state.incidents.find(x=>x.id===t.dataset.editIncident));if(t.dataset.editNote)return noteModal(state.notes.find(x=>x.id===t.dataset.editNote));if(t.dataset.viewReport){const r=state.reports.find(x=>x.id===t.dataset.viewReport);modal(`<h2>歷史通報</h2><div class="rule-source">${H(r.reportText||'')}</div><button class="btn" id="copyHistoric">複製</button>`);$('#copyHistoric').onclick=()=>copyText(r.reportText||'');return;}if(t.dataset.deleteUnit!==undefined){draft().unitAttendance.splice(+t.dataset.deleteUnit,1);render();return;}if(t.dataset.deleteNote){if(confirm('確定刪除此備註？')){await deleteDoc('notes',t.dataset.deleteNote);await refresh();}return;}if(t.dataset.deleteEvent){const id=t.dataset.deleteEvent;if(state.reports.some(r=>r.eventId===id)||state.incidents.some(r=>r.eventId===id)){alert('此事件已有通報或異常紀錄，不允許直接刪除以免破壞歷史；請保留事件。');return;}if(confirm('確定刪除空白事件？')){await deleteDoc('events',id);await refresh();}}}catch(e){toast(e.message,'error');}});
document.addEventListener('change',e=>{const t=e.target,d=state.eventId?draft():null;if(t.dataset.global==='event'){state.eventId=t.value;render();return;}if(!d)return;if(t.dataset.staffSlot){const k=t.dataset.staffSlot;const item=k===state.slotId?d:(state.drafts[state.eventId+'__'+k]|| (state.drafts[state.eventId+'__'+k]=(()=>{let prev=state.slotId;state.slotId=k;const x=initialDraft();state.slotId=prev;return x;})()));item.peopleIds=item.peopleIds||[];item.peopleIds=t.checked?[...new Set([...item.peopleIds,t.dataset.person])]:item.peopleIds.filter(x=>x!==t.dataset.person);render();return;}if(t.dataset.status){d.checks[t.dataset.status]=t.value;updatePreview();return;}if(t.dataset.field){d[t.dataset.field]=t.value;updatePreview();return;}if(t.dataset.unit!==undefined){d.unitAttendance[+t.dataset.unit][t.dataset.prop]=t.value;updatePreview();return;}if(t.dataset.patrol){d.patrol[t.dataset.patrol]=t.value;updatePreview();return;}if(t.dataset.weather){d.weather[t.dataset.weather]=t.value;updatePreview();return;}if(t.dataset.note){d.notes[t.dataset.note]=t.value;updatePreview();return;}});
document.addEventListener('input',e=>{const t=e.target,d=state.eventId?draft():null;if(!d)return;if(t.dataset.field)d[t.dataset.field]=t.value;if(t.dataset.note)d.notes[t.dataset.note]=t.value;if(t.dataset.weather)d.weather[t.dataset.weather]=t.value;if(t.dataset.patrol)d.patrol[t.dataset.patrol]=t.value;if(t.dataset.unit!==undefined)d.unitAttendance[+t.dataset.unit][t.dataset.prop]=t.value;updatePreview();});
document.addEventListener('submit',async e=>{if(!['eventForm','staffForm','incidentForm','ruleForm','noteForm','settingsForm'].includes(e.target.id))return;e.preventDefault();if(!isOwner())return;const f=e.target,v=Object.fromEntries(new FormData(f).entries());try{if(f.id==='eventForm'){const obj={id:v.id||makeId(),name:clean(v.name),factory:v.factory,date:v.date};await saveDoc('events',obj);}if(f.id==='staffForm'){const obj={id:v.id||makeId(),name:clean(v.name),factory:v.factory,unit:v.unit,job:v.job,phone:v.phone,active:f.elements.active.checked};await saveDoc('staff',obj);}if(f.id==='incidentForm'){const obj={id:v.id||makeId(),eventId:state.eventId,at:v.at,title:v.title,details:v.details,action:v.action};for(const k of ['groupNotified','supervisorContacted','photoAttached','closed'])obj[k]=f.elements[k].checked;await saveDoc('incidents',obj);}if(f.id==='ruleForm'){const section=SECTIONS.find(x=>x.id===state.sectionId),before=state.rules.find(x=>x.id===section.id)?.text||section.text;await saveDoc('revisions',{id:makeId(),sectionId:section.id,at:now(),before,after:v.text,reason:v.reason});await saveDoc('rules',{id:section.id,text:v.text,reason:v.reason,updatedAt:now()});}if(f.id==='noteForm'){const old=state.notes.find(x=>x.id===v.id);await saveDoc('notes',{...old,id:v.id||makeId(),sectionId:state.sectionId,text:v.text,author:currentUser()?.email||'管理員',createdAt:old?.createdAt||now(),updatedAt:now()});}if(f.id==='settingsForm'){const units={};FACTORIES.forEach(x=>units[x]=(f.elements['units_'+x].value||'').split(/\r?\n/).map(clean).filter(Boolean));await saveDoc('settings',{id:'general',recipient:v.recipient,units});}document.querySelector('.modal-shade')?.remove();toast('資料已儲存');await refresh();}catch(err){toast(err.message,'error');}});
$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');
init(async()=>{try{await refresh();if(mode==='firebase'&&!currentUser()){$('#main').insertAdjacentHTML('afterbegin',`<div class="banner warning">尚未登入。請先使用EHS既有登入機制完成Firebase Authentication，再重新開啟本頁。若入口站與子系統不共用登入狀態，需依實際入口架構整合。</div><div class="panel"><h3>既有Firebase帳密登入</h3><form id="loginForm"><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>密碼</label><input name="password" type="password" required></div><button class="btn">登入</button></form></div>`);$('#loginForm').onsubmit=async e=>{e.preventDefault();try{await signIn(e.target.email.value,e.target.password.value);}catch(err){toast(err.message,'error');}};}}catch(e){mainError(e);}}).catch(mainError);
